 matched=[x for x in catalog['claims'] if names.intersection(__import__('re').findall(r'Host\w+(?:Attack|Aim)',x['helper']))]
 raw=sorted({p for x in matched for p in x['rawArtifactRefs']})
 result.append(dict(nativeLine=r['line'],nativeMethod=r['method'],event=r['callee'],actualSource=a,stage=stage,nativeConsumer=consumer,classification=kind,evidence=proof,mechanismReferences=';'.join(sorted(names)),rawEvidenceReferences=';'.join(raw),closure='SOURCE_CLASSIFIED; mechanism catalog component identities retained; final full Effects and ordinary07 do not inherit PASS',verificationBoundary='mechanism-evidence-index.json contains owner claim / exact raw SHA; no per-event or per-combination runtime inference',causality='OnHit-born actors require an actual preceding native receiver; direct primary Contact does not prove secondary independent reachability' if 'OnHit' in stage or r['method']=='Damage_PVE_Inner' else 'native source/slot/phase and family conditions retained'))
